export function getHelpCategory(id: string): HelpCategory | undefined {
  return HELP_CATEGORIES.find((cat) => cat.id === id);
}

export function getHelpArticle(categoryId: string, articleSlug: string): HelpArticle | undefined {
  const category = getHelpCategory(categoryId);
  return category?.articles.find((a) => a.slug === articleSlug);
}

export function getAllHelpArticles(): { category: HelpCategory; article: HelpArticle }[] {
  return HELP_CATEGORIES.flatMap((category) =>
    category.articles.map((article) => ({ category, article }))
  );
}
